  logic w_i2s_rx_ctrl_flush_nxt;
  logic reg_i2s_rx_ctrl_srst;
  logic w_i2s_rx_ctrl_srst_nxt;
  logic reg_i2s_rx_ctrl_en;
  logic w_i2s_rx_ctrl_en_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_ctrl_value;
  logic w_we_i2s_rx_frame;
  logic [5:0] reg_i2s_rx_frame_data_w;
  logic [5:0] w_i2s_rx_frame_data_w_nxt;
  logic [5:0] reg_i2s_rx_frame_slot_w;
  logic [5:0] w_i2s_rx_frame_slot_w_nxt;
  logic [5:0] reg_i2s_rx_frame_nslot;
  logic [5:0] w_i2s_rx_frame_nslot_nxt;
  logic reg_i2s_rx_frame_pack;
  logic w_i2s_rx_frame_pack_nxt;
  logic reg_i2s_rx_frame_align;
  logic w_i2s_rx_frame_align_nxt;
  logic [2:0] reg_i2s_rx_frame_fmt;
  logic [2:0] w_i2s_rx_frame_fmt_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_frame_value;
  logic w_we_i2s_rx_sync;
  logic reg_i2s_rx_sync_bpol;
  logic w_i2s_rx_sync_bpol_nxt;
  logic reg_i2s_rx_sync_fse;
  logic w_i2s_rx_sync_fse_nxt;
  logic reg_i2s_rx_sync_fsp;
  logic w_i2s_rx_sync_fsp_nxt;
  logic [5:0] reg_i2s_rx_sync_sync_w;
  logic [5:0] w_i2s_rx_sync_sync_w_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_sync_value;
  logic w_we_i2s_rx_clk;
  logic [15:0] reg_i2s_rx_clk_div;
  logic [15:0] w_i2s_rx_clk_div_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_clk_value;
  logic w_we_i2s_rx_mask;
  logic [31:0] reg_i2s_rx_mask_mask;
  logic [31:0] w_i2s_rx_mask_mask_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_mask_value;
  logic w_we_i2s_rx_fifo;
  logic [11:0] reg_i2s_rx_fifo_wm;
  logic [11:0] w_i2s_rx_fifo_wm_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_fifo_value;
  logic w_we_i2s_rx_sts;
  logic reg_i2s_rx_sts_hung;
  logic w_i2s_rx_sts_hung_nxt;
  logic reg_i2s_rx_sts_sync;
  logic w_i2s_rx_sts_sync_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_sts_value;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_data_value;
  logic w_we_i2s_rx_tmo;
  logic [15:0] reg_i2s_rx_tmo_tmo;
  logic [15:0] w_i2s_rx_tmo_tmo_nxt;
  logic [LPARA_DATA_W-1:0] w_i2s_rx_tmo_value;

  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Write byte strobes are captured with the write payload and expanded to field-bit masks.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign w_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_i2s_ctrl = w_wr_en & (reg_addr == LPARA_I2S_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_irq_raw = w_wr_en & (reg_addr == LPARA_I2S_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_irq_en = w_wr_en & (reg_addr == LPARA_I2S_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_irq_inj = w_wr_en & (reg_addr == LPARA_I2S_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_ctrl = w_wr_en & (reg_addr == LPARA_I2S_TX_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_frame = w_wr_en & (reg_addr == LPARA_I2S_TX_FRAME_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_sync = w_wr_en & (reg_addr == LPARA_I2S_TX_SYNC_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_clk = w_wr_en & (reg_addr == LPARA_I2S_TX_CLK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_mask = w_wr_en & (reg_addr == LPARA_I2S_TX_MASK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_fifo = w_wr_en & (reg_addr == LPARA_I2S_TX_FIFO_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_sts = w_wr_en & (reg_addr == LPARA_I2S_TX_STS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_data = w_wr_en & (reg_addr == LPARA_I2S_TX_DATA_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_tx_tmo = w_wr_en & (reg_addr == LPARA_I2S_TX_TMO_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_ctrl = w_wr_en & (reg_addr == LPARA_I2S_RX_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_frame = w_wr_en & (reg_addr == LPARA_I2S_RX_FRAME_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_sync = w_wr_en & (reg_addr == LPARA_I2S_RX_SYNC_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_clk = w_wr_en & (reg_addr == LPARA_I2S_RX_CLK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_mask = w_wr_en & (reg_addr == LPARA_I2S_RX_MASK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_fifo = w_wr_en & (reg_addr == LPARA_I2S_RX_FIFO_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_sts = w_wr_en & (reg_addr == LPARA_I2S_RX_STS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_i2s_rx_tmo = w_wr_en & (reg_addr == LPARA_I2S_RX_TMO_OFFSET[LPARA_ADDR_W-1:0]);

  // Register transaction events are qualified by the captured APB transfer.
  // Read events include aligned unmapped reads, which return zero. Unaligned reads
  // are suppressed even when the APB error response is disabled.
  assign o_reg_rd_en   = w_rd_en & (reg_addr[1:0] == 2'b00);
  assign o_reg_rd_addr = o_reg_rd_en ? reg_addr : '0;

  // Write events are asserted only for a mapped register with at least one
  // software-writable field; rejected and read-only writes do not assert this event.
  assign o_reg_wr_en   =
    (|w_we_i2s_ctrl)
    | (|w_we_i2s_irq_raw)
    | (|w_we_i2s_irq_en)
    | (|w_we_i2s_irq_inj)
    | (|w_we_i2s_tx_ctrl)
    | (|w_we_i2s_tx_frame)
    | (|w_we_i2s_tx_sync)
    | (|w_we_i2s_tx_clk)
    | (|w_we_i2s_tx_mask)
    | (|w_we_i2s_tx_fifo)
    | (|w_we_i2s_tx_sts)
    | (|w_we_i2s_tx_data)
    | (|w_we_i2s_tx_tmo)
    | (|w_we_i2s_rx_ctrl)
    | (|w_we_i2s_rx_frame)
    | (|w_we_i2s_rx_sync)
    | (|w_we_i2s_rx_clk)
    | (|w_we_i2s_rx_mask)
    | (|w_we_i2s_rx_fifo)
    | (|w_we_i2s_rx_sts)
    | (|w_we_i2s_rx_tmo);
  assign o_reg_wr_addr = o_reg_wr_en ? reg_addr : '0;

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

      // PREADY pulses after an acknowledged operation or a SETUP-phase error.
      assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end else begin : g_sync_csr

      // Synchronous-only request capture and response state.
      logic reg_rd_capture;
      logic reg_wr_capture;
      logic w_pready_nxt;
      logic reg_pready;

      // Read/write enables are delayed one cycle in synchronous mode.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
        if (!i_rst_n_apb) begin
          reg_rd_capture <= 1'b0;
          reg_wr_capture <= 1'b0;
        end else begin
          reg_rd_capture <= w_apb_rd;
          reg_wr_capture <= w_apb_wr;
        end
      end
      assign w_rd_en = reg_rd_capture;
      assign w_wr_en = reg_wr_capture;
      assign w_rd_ack_fall = 1'b0;

      // PREADY pulses after an operation or a SETUP-phase error.
      assign w_pready_nxt = w_wr_en | w_rd_en | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end
  endgenerate

  // Register i2s_version: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_version_value
    w_i2s_version_value = '0;
    w_i2s_version_value[31:16] = i_i2s_version_major;
    w_i2s_version_value[15:0] = i_i2s_version_minor;
  end

  // Register i2s_cap: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_cap_value
    w_i2s_cap_value = '0;
    w_i2s_cap_value[30] = i_i2s_cap_fmt_ext;
    w_i2s_cap_value[29] = i_i2s_cap_dma;
    w_i2s_cap_value[28] = i_i2s_cap_hung;
    w_i2s_cap_value[27] = i_i2s_cap_tri;
    w_i2s_cap_value[26] = i_i2s_cap_ondem;
    w_i2s_cap_value[25] = i_i2s_cap_div;
    w_i2s_cap_value[24] = i_i2s_cap_pack;
    w_i2s_cap_value[21:16] = i_i2s_cap_max_slot;
    w_i2s_cap_value[15:12] = i_i2s_cap_depth_l2;
    w_i2s_cap_value[10:8] = i_i2s_cap_rx_lines;
    w_i2s_cap_value[6:4] = i_i2s_cap_tx_lines;
    w_i2s_cap_value[1] = i_i2s_cap_rx_pres;
    w_i2s_cap_value[0] = i_i2s_cap_tx_pres;
  end

  // i2s_ctrl_frm_sel next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_ctrl_frm_sel_nxt = (w_we_i2s_ctrl & (|w_wmask[4])) ? ((reg_wdata[4] & w_wmask[4]) | (reg_i2s_ctrl_frm_sel & ~w_wmask[4])) : reg_i2s_ctrl_frm_sel;

  // i2s_ctrl_srst next value (wo): hardware clear overrides software writes.
  assign w_i2s_ctrl_srst_nxt = i_hw_clr_i2s_ctrl_srst ? '0
               : (w_we_i2s_ctrl & (|w_wmask[0])) ? ((reg_wdata[0] & w_wmask[0]) | (reg_i2s_ctrl_srst & ~w_wmask[0]))
               : reg_i2s_ctrl_srst;

  // Register i2s_ctrl: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_ctrl
    if (!w_rst_n_reg) begin
      reg_i2s_ctrl_frm_sel <= 1'h0;
      reg_i2s_ctrl_srst <= 1'h0;
    end else begin
      reg_i2s_ctrl_frm_sel <= w_i2s_ctrl_frm_sel_nxt;
      reg_i2s_ctrl_srst <= w_i2s_ctrl_srst_nxt;
    end
  end

  // Register i2s_ctrl: output ports follow the flops.
  assign o_i2s_ctrl_frm_sel = reg_i2s_ctrl_frm_sel;
  assign o_i2s_ctrl_srst = reg_i2s_ctrl_srst;

  // Register i2s_ctrl: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_ctrl_value
    w_i2s_ctrl_value = '0;
    w_i2s_ctrl_value[4] = reg_i2s_ctrl_frm_sel;
  end

  // Register i2s_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_sts_value
    w_i2s_sts_value = '0;
    w_i2s_sts_value[4] = i_i2s_sts_irq;
    w_i2s_sts_value[1] = i_i2s_sts_rx_busy;
    w_i2s_sts_value[0] = i_i2s_sts_tx_busy;
  end

  // i2s_irq_raw_frm next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_irq_raw_frm_nxt = (i_hw_we_i2s_irq_raw_frm) ? i_hw_wdata_i2s_irq_raw_frm
                          : ((w_we_i2s_irq_raw & (|w_wmask[7])) ? (reg_i2s_irq_raw_frm & ~(reg_wdata[7] & w_wmask[7])) : reg_i2s_irq_raw_frm);

  // i2s_irq_raw_hung next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_irq_raw_hung_nxt = (i_hw_we_i2s_irq_raw_hung) ? i_hw_wdata_i2s_irq_raw_hung
                          : ((w_we_i2s_irq_raw & (|w_wmask[6])) ? (reg_i2s_irq_raw_hung & ~(reg_wdata[6] & w_wmask[6])) : reg_i2s_irq_raw_hung);

  // i2s_irq_raw_sync next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_irq_raw_sync_nxt = (i_hw_we_i2s_irq_raw_sync) ? i_hw_wdata_i2s_irq_raw_sync
                          : ((w_we_i2s_irq_raw & (|w_wmask[5])) ? (reg_i2s_irq_raw_sync & ~(reg_wdata[5] & w_wmask[5])) : reg_i2s_irq_raw_sync);

  // i2s_irq_raw_rx_ovr next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_irq_raw_rx_ovr_nxt = (i_hw_we_i2s_irq_raw_rx_ovr) ? i_hw_wdata_i2s_irq_raw_rx_ovr
                          : ((w_we_i2s_irq_raw & (|w_wmask[4])) ? (reg_i2s_irq_raw_rx_ovr & ~(reg_wdata[4] & w_wmask[4])) : reg_i2s_irq_raw_rx_ovr);

