      reg_i2s_rx_frame_data_w <= w_i2s_rx_frame_data_w_nxt;
      reg_i2s_rx_frame_slot_w <= w_i2s_rx_frame_slot_w_nxt;
      reg_i2s_rx_frame_nslot <= w_i2s_rx_frame_nslot_nxt;
      reg_i2s_rx_frame_pack <= w_i2s_rx_frame_pack_nxt;
      reg_i2s_rx_frame_align <= w_i2s_rx_frame_align_nxt;
      reg_i2s_rx_frame_fmt <= w_i2s_rx_frame_fmt_nxt;
