  end

  // Register i2s_rx_frame: output ports follow the flops.
  assign o_i2s_rx_frame_data_w = reg_i2s_rx_frame_data_w;
  assign o_i2s_rx_frame_slot_w = reg_i2s_rx_frame_slot_w;
  assign o_i2s_rx_frame_nslot = reg_i2s_rx_frame_nslot;
  assign o_i2s_rx_frame_pack = reg_i2s_rx_frame_pack;
  assign o_i2s_rx_frame_align = reg_i2s_rx_frame_align;
  assign o_i2s_rx_frame_fmt = reg_i2s_rx_frame_fmt;

  // Register i2s_rx_frame: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_frame_value
    w_i2s_rx_frame_value = '0;
    w_i2s_rx_frame_value[29:24] = reg_i2s_rx_frame_data_w;
    w_i2s_rx_frame_value[21:16] = reg_i2s_rx_frame_slot_w;
    w_i2s_rx_frame_value[13:8] = reg_i2s_rx_frame_nslot;
    w_i2s_rx_frame_value[4] = reg_i2s_rx_frame_pack;
    w_i2s_rx_frame_value[3] = reg_i2s_rx_frame_align;
    w_i2s_rx_frame_value[2:0] = reg_i2s_rx_frame_fmt;
  end

  // i2s_rx_sync_bpol next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_sync_bpol_nxt = (w_we_i2s_rx_sync & (|w_wmask[12])) ? ((reg_wdata[12] & w_wmask[12]) | (reg_i2s_rx_sync_bpol & ~w_wmask[12])) : reg_i2s_rx_sync_bpol;

  // i2s_rx_sync_fse next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_sync_fse_nxt = (w_we_i2s_rx_sync & (|w_wmask[9])) ? ((reg_wdata[9] & w_wmask[9]) | (reg_i2s_rx_sync_fse & ~w_wmask[9])) : reg_i2s_rx_sync_fse;

  // i2s_rx_sync_fsp next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_sync_fsp_nxt = (w_we_i2s_rx_sync & (|w_wmask[8])) ? ((reg_wdata[8] & w_wmask[8]) | (reg_i2s_rx_sync_fsp & ~w_wmask[8])) : reg_i2s_rx_sync_fsp;

  // i2s_rx_sync_sync_w next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_sync_sync_w_nxt = (w_we_i2s_rx_sync & (|w_wmask[5:0])) ? ((reg_wdata[5:0] & w_wmask[5:0]) | (reg_i2s_rx_sync_sync_w & ~w_wmask[5:0])) : reg_i2s_rx_sync_sync_w;

  // Register i2s_rx_sync: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_sync
    if (!w_rst_n_reg) begin
      reg_i2s_rx_sync_bpol <= 1'h0;
      reg_i2s_rx_sync_fse <= 1'h1;
      reg_i2s_rx_sync_fsp <= 1'h0;
      reg_i2s_rx_sync_sync_w <= 6'h1;
    end else begin
      reg_i2s_rx_sync_bpol <= w_i2s_rx_sync_bpol_nxt;
      reg_i2s_rx_sync_fse <= w_i2s_rx_sync_fse_nxt;
      reg_i2s_rx_sync_fsp <= w_i2s_rx_sync_fsp_nxt;
      reg_i2s_rx_sync_sync_w <= w_i2s_rx_sync_sync_w_nxt;
    end
  end

  // Register i2s_rx_sync: output ports follow the flops.
  assign o_i2s_rx_sync_bpol = reg_i2s_rx_sync_bpol;
  assign o_i2s_rx_sync_fse = reg_i2s_rx_sync_fse;
  assign o_i2s_rx_sync_fsp = reg_i2s_rx_sync_fsp;
  assign o_i2s_rx_sync_sync_w = reg_i2s_rx_sync_sync_w;

  // Register i2s_rx_sync: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_sync_value
    w_i2s_rx_sync_value = '0;
    w_i2s_rx_sync_value[12] = reg_i2s_rx_sync_bpol;
    w_i2s_rx_sync_value[9] = reg_i2s_rx_sync_fse;
    w_i2s_rx_sync_value[8] = reg_i2s_rx_sync_fsp;
    w_i2s_rx_sync_value[5:0] = reg_i2s_rx_sync_sync_w;
  end

  // i2s_rx_clk_div next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_clk_div_nxt = (w_we_i2s_rx_clk & (|w_wmask[15:0])) ? ((reg_wdata[15:0] & w_wmask[15:0]) | (reg_i2s_rx_clk_div & ~w_wmask[15:0])) : reg_i2s_rx_clk_div;

  // Register i2s_rx_clk: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_clk
    if (!w_rst_n_reg) begin
      reg_i2s_rx_clk_div <= 16'h2;
    end else begin
      reg_i2s_rx_clk_div <= w_i2s_rx_clk_div_nxt;
    end
  end

  // Register i2s_rx_clk: output ports follow the flops.
  assign o_i2s_rx_clk_div = reg_i2s_rx_clk_div;

  // Register i2s_rx_clk: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_clk_value
    w_i2s_rx_clk_value = '0;
    w_i2s_rx_clk_value[15:0] = reg_i2s_rx_clk_div;
  end

  // i2s_rx_mask_mask next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_mask_mask_nxt = (w_we_i2s_rx_mask & (|w_wmask[31:0])) ? ((reg_wdata[31:0] & w_wmask[31:0]) | (reg_i2s_rx_mask_mask & ~w_wmask[31:0])) : reg_i2s_rx_mask_mask;

  // Register i2s_rx_mask: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_mask
    if (!w_rst_n_reg) begin
      reg_i2s_rx_mask_mask <= 32'hffffffff;
    end else begin
      reg_i2s_rx_mask_mask <= w_i2s_rx_mask_mask_nxt;
    end
  end

  // Register i2s_rx_mask: output ports follow the flops.
  assign o_i2s_rx_mask_mask = reg_i2s_rx_mask_mask;

  // Register i2s_rx_mask: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_mask_value
    w_i2s_rx_mask_value = '0;
    w_i2s_rx_mask_value[31:0] = reg_i2s_rx_mask_mask;
  end

  // i2s_rx_fifo_wm next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_fifo_wm_nxt = (w_we_i2s_rx_fifo & (|w_wmask[11:0])) ? ((reg_wdata[11:0] & w_wmask[11:0]) | (reg_i2s_rx_fifo_wm & ~w_wmask[11:0])) : reg_i2s_rx_fifo_wm;

  // Register i2s_rx_fifo: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_fifo
    if (!w_rst_n_reg) begin
      reg_i2s_rx_fifo_wm <= 12'h4;
    end else begin
      reg_i2s_rx_fifo_wm <= w_i2s_rx_fifo_wm_nxt;
    end
  end

  // Register i2s_rx_fifo: output ports follow the flops.
  assign o_i2s_rx_fifo_wm = reg_i2s_rx_fifo_wm;

  // Register i2s_rx_fifo: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_fifo_value
    w_i2s_rx_fifo_value = '0;
    w_i2s_rx_fifo_value[11:0] = reg_i2s_rx_fifo_wm;
  end

  // i2s_rx_sts_hung next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_rx_sts_hung_nxt = (i_hw_we_i2s_rx_sts_hung) ? i_hw_wdata_i2s_rx_sts_hung
                          : ((w_we_i2s_rx_sts & (|w_wmask[5])) ? (reg_i2s_rx_sts_hung & ~(reg_wdata[5] & w_wmask[5])) : reg_i2s_rx_sts_hung);

  // i2s_rx_sts_sync next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_i2s_rx_sts_sync_nxt = (i_hw_we_i2s_rx_sts_sync) ? i_hw_wdata_i2s_rx_sts_sync
                          : ((w_we_i2s_rx_sts & (|w_wmask[4])) ? (reg_i2s_rx_sts_sync & ~(reg_wdata[4] & w_wmask[4])) : reg_i2s_rx_sts_sync);

  // Register i2s_rx_sts: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_sts
    if (!w_rst_n_reg) begin
      reg_i2s_rx_sts_hung <= 1'h0;
      reg_i2s_rx_sts_sync <= 1'h0;
    end else begin
      reg_i2s_rx_sts_hung <= w_i2s_rx_sts_hung_nxt;
      reg_i2s_rx_sts_sync <= w_i2s_rx_sts_sync_nxt;
    end
  end

  // Register i2s_rx_sts: output ports follow the flops.
  assign o_i2s_rx_sts_hung = reg_i2s_rx_sts_hung;
  assign o_i2s_rx_sts_sync = reg_i2s_rx_sts_sync;

  // Register i2s_rx_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_sts_value
    w_i2s_rx_sts_value = '0;
    w_i2s_rx_sts_value[27:16] = i_i2s_rx_sts_level;
    w_i2s_rx_sts_value[5] = reg_i2s_rx_sts_hung;
    w_i2s_rx_sts_value[4] = reg_i2s_rx_sts_sync;
    w_i2s_rx_sts_value[2] = i_i2s_rx_sts_full;
    w_i2s_rx_sts_value[1] = i_i2s_rx_sts_empty;
    w_i2s_rx_sts_value[0] = i_i2s_rx_sts_busy;
  end

  // Register i2s_rx_data: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_data_value
    w_i2s_rx_data_value = '0;
    w_i2s_rx_data_value[31:0] = i_i2s_rx_data_data;
  end

  // i2s_rx_tmo_tmo next value (rw): update only byte lanes selected by the bus strobe.
  assign w_i2s_rx_tmo_tmo_nxt = (w_we_i2s_rx_tmo & (|w_wmask[15:0])) ? ((reg_wdata[15:0] & w_wmask[15:0]) | (reg_i2s_rx_tmo_tmo & ~w_wmask[15:0])) : reg_i2s_rx_tmo_tmo;

  // Register i2s_rx_tmo: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_i2s_rx_tmo
    if (!w_rst_n_reg) begin
      reg_i2s_rx_tmo_tmo <= 16'h0;
    end else begin
      reg_i2s_rx_tmo_tmo <= w_i2s_rx_tmo_tmo_nxt;
    end
  end

  // Register i2s_rx_tmo: output ports follow the flops.
  assign o_i2s_rx_tmo_tmo = reg_i2s_rx_tmo_tmo;

  // Register i2s_rx_tmo: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_i2s_rx_tmo_value
    w_i2s_rx_tmo_value = '0;
    w_i2s_rx_tmo_value[15:0] = reg_i2s_rx_tmo_tmo;
  end

  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_I2S_VERSION_OFFSET: w_rdata_nxt = w_i2s_version_value;
      LPARA_I2S_CAP_OFFSET: w_rdata_nxt = w_i2s_cap_value;
      LPARA_I2S_CTRL_OFFSET: w_rdata_nxt = w_i2s_ctrl_value;
      LPARA_I2S_STS_OFFSET: w_rdata_nxt = w_i2s_sts_value;
      LPARA_I2S_IRQ_RAW_OFFSET: w_rdata_nxt = w_i2s_irq_raw_value;
      LPARA_I2S_IRQ_EN_OFFSET: w_rdata_nxt = w_i2s_irq_en_value;
      LPARA_I2S_IRQ_INJ_OFFSET: w_rdata_nxt = w_i2s_irq_inj_value;
      LPARA_I2S_IRQ_STS_OFFSET: w_rdata_nxt = w_i2s_irq_sts_value;
      LPARA_I2S_TX_CTRL_OFFSET: w_rdata_nxt = w_i2s_tx_ctrl_value;
      LPARA_I2S_TX_FRAME_OFFSET: w_rdata_nxt = w_i2s_tx_frame_value;
      LPARA_I2S_TX_SYNC_OFFSET: w_rdata_nxt = w_i2s_tx_sync_value;
      LPARA_I2S_TX_CLK_OFFSET: w_rdata_nxt = w_i2s_tx_clk_value;
      LPARA_I2S_TX_MASK_OFFSET: w_rdata_nxt = w_i2s_tx_mask_value;
      LPARA_I2S_TX_FIFO_OFFSET: w_rdata_nxt = w_i2s_tx_fifo_value;
      LPARA_I2S_TX_STS_OFFSET: w_rdata_nxt = w_i2s_tx_sts_value;
      LPARA_I2S_TX_DATA_OFFSET: w_rdata_nxt = w_i2s_tx_data_value;
      LPARA_I2S_TX_TMO_OFFSET: w_rdata_nxt = w_i2s_tx_tmo_value;
      LPARA_I2S_RX_CTRL_OFFSET: w_rdata_nxt = w_i2s_rx_ctrl_value;
      LPARA_I2S_RX_FRAME_OFFSET: w_rdata_nxt = w_i2s_rx_frame_value;
      LPARA_I2S_RX_SYNC_OFFSET: w_rdata_nxt = w_i2s_rx_sync_value;
      LPARA_I2S_RX_CLK_OFFSET: w_rdata_nxt = w_i2s_rx_clk_value;
      LPARA_I2S_RX_MASK_OFFSET: w_rdata_nxt = w_i2s_rx_mask_value;
      LPARA_I2S_RX_FIFO_OFFSET: w_rdata_nxt = w_i2s_rx_fifo_value;
      LPARA_I2S_RX_STS_OFFSET: w_rdata_nxt = w_i2s_rx_sts_value;
      LPARA_I2S_RX_DATA_OFFSET: w_rdata_nxt = w_i2s_rx_data_value;
      LPARA_I2S_RX_TMO_OFFSET: w_rdata_nxt = w_i2s_rx_tmo_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
